fn check(label: &str, code: &str, source: HtmlFileSource) -> usize {
    let parsed = parse_html(code, (&source).into());
    let root = parsed.tree();
    let rule_filter = RuleFilter::Rule("a11y", "useHeadingContent");
    let filter = AnalysisFilter {
        enabled_rules: Some(&[rule_filter]),
        ..AnalysisFilter::default()
    };
    let options = biome_analyze::AnalyzerOptions::default();
