    analyze(
        &root,
        filter,
        &options,
        source,
        HtmlAnalyzerServices::default(),
        |signal| {
            if signal.diagnostic().is_some() {
                count += 1;
            }
            ControlFlow::<Never>::Continue(())
        },
    );
    println!("[{count}] {label}: {code:?}");
    count
}

